// Title: Add a SUM formula to a smart‑marker‑driven Excel sheet with Aspose.Cells in C#
// Common Searches: how to add a sum formula to a smart marker template using Aspose.Cells in C# | Aspose.Cells C# calculate totals after processing smart markers | embed dynamic formula in Excel generated by WorkbookDesigner Aspose.Cells | use WorkbookDesigner to insert formulas that reference smart marker data in C#
// Tags: Aspose.Cells WorkbookDesigner add formula | C# embed SUM function in smart marker template | dynamic total calculation after smart marker processing | Excel file generation with formulas using Aspose.Cells | recalculate formulas after smart marker data binding

using System;
using System.Collections.Generic;
using System.IO;
using Aspose.Cells;

// The example creates a workbook, places smart markers for Item and Amount, inserts a SUM formula in cell B6, binds a list of objects as the "Data" source, processes the markers with WorkbookDesigner, recalculates all formulas, and saves the result as SmartMarkerWithFormula.xlsx.
class Program
{
    static void Main()
    {
        try
        {
            // Create a new workbook and get the first worksheet
            Workbook wb = new Workbook();
            Worksheet ws = wb.Worksheets[0];

            // Set column headers
            ws.Cells["A1"].PutValue("Item");
            ws.Cells["B1"].PutValue("Amount");

            // Insert smart markers for the data rows (starting at row 2)
            ws.Cells["A2"].PutValue("{Data!Item}");
            ws.Cells["B2"].PutValue("{Data!Amount}");

            // Add a formula that sums the Amount column.
            ws.Cells["A6"].PutValue("Total");
            ws.Cells["B6"].Formula = "SUM(B2:B5)";

            // Prepare the data source for the smart markers
            var data = new List<object>
            {
                new { Item = "Apple",  Amount = 10 },
                new { Item = "Banana", Amount = 20 },
                new { Item = "Orange", Amount = 15 },
                new { Item = "Grape",  Amount = 5  }
            };

            // Process the smart markers using WorkbookDesigner
            WorkbookDesigner designer = new WorkbookDesigner(wb);
            // Correct overload: first parameter is the name, second is the data source
            designer.SetDataSource("Data", data);
            designer.Process();

            // Recalculate formulas so the total reflects the inserted values
            wb.CalculateFormula();

            // Determine output file path and ensure the directory exists
            string outputPath = "SmartMarkerWithFormula.xlsx";
            string outputDir = Path.GetDirectoryName(Path.GetFullPath(outputPath));

            if (!string.IsNullOrEmpty(outputDir) && !Directory.Exists(outputDir))
            {
                Directory.CreateDirectory(outputDir);
            }

            // Save the resulting workbook
            wb.Save(outputPath);
            Console.WriteLine($"Workbook saved to: {Path.GetFullPath(outputPath)}");
        }
        catch (Exception ex)
        {
            Console.WriteLine($"Error: {ex.Message}");
        }
    }
}
